import { useState, useEffect } from 'react';
import axios from '../../api/axiosInstance';
import { FaUserShield, FaLock, FaCog } from 'react-icons/fa';

const SystemSettings = () => {
    const [settings, setSettings] = useState({ siteTitle: '', maintenance: false });
    const [roles, setRoles] = useState([]);
    const [users, setUsers] = useState([]);

    useEffect(() => {
        fetchSettings();
        fetchUsers();
    }, []);

    const fetchSettings = async () => {
        const res = await axios.get('/settings');
        setSettings(res.data);
    };

    const fetchUsers = async () => {
        const res = await axios.get('/users');
        setUsers(res.data);
    };

    const handleSaveSettings = async () => {
        await axios.put('/settings', settings);
        alert('Đã lưu cấu hình hệ thống');
    };

    const handleChangeRole = async (userId, role) => {
        await axios.put(`/users/${userId}/role`, { role });
        fetchUsers();
        alert('Cập nhật quyền thành công');
    };

    return (
        <div style={{ padding: 20 }}>
            <h2 style={{ display: 'flex', alignItems: 'center', gap: 10 }}><FaCog /> Cài đặt hệ thống</h2>

            <div style={card}>
                <h3><FaCog /> Cấu hình chung</h3>
                <input
                    type="text"
                    value={settings.siteTitle}
                    onChange={(e) => setSettings({ ...settings, siteTitle: e.target.value })}
                    placeholder="Tiêu đề hệ thống"
                    style={inputStyle}
                />
                <label>
                    <input
                        type="checkbox"
                        checked={settings.maintenance}
                        onChange={(e) => setSettings({ ...settings, maintenance: e.target.checked })}
                    /> Bảo trì hệ thống
                </label>
                <button onClick={handleSaveSettings} style={btn}>💾 Lưu cấu hình</button>
            </div>

            <div style={card}>
                <h3><FaUserShield /> Phân quyền người dùng</h3>
                <table border="1" cellPadding="10" style={{ width: '100%', textAlign: 'center' }}>
                    <thead style={{ backgroundColor: '#f0f8ff' }}>
                        <tr>
                            <th>Tên</th>
                            <th>Email</th>
                            <th>Vai trò</th>
                            <th>Đổi quyền</th>
                        </tr>
                    </thead>
                    <tbody>
                        {users.map(u => (
                            <tr key={u._id}>
                                <td>{u.name}</td>
                                <td>{u.email}</td>
                                <td>{u.role}</td>
                                <td>
                                    <select
                                        value={u.role}
                                        onChange={(e) => handleChangeRole(u._id, e.target.value)}
                                    >
                                        <option value="user">Người dùng</option>
                                        <option value="admin">Quản trị viên</option>
                                        <option value="accountant">Kế toán</option>
                                    </select>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>

            <div style={card}>
                <h3><FaLock /> Bảo mật</h3>
                <p>Mật khẩu của người dùng được mã hóa và lưu trữ an toàn.</p>
                <p>Hệ thống sử dụng xác thực JWT và kiểm tra quyền truy cập.</p>
            </div>
        </div>
    );
};

const card = {
    background: '#fff',
    borderRadius: 10,
    boxShadow: '0 0 10px rgba(0,0,0,0.05)',
    padding: 20,
    marginBottom: 30
};

const inputStyle = {
    width: '100%',
    padding: 10,
    marginBottom: 10,
    border: '1px solid #ccc',
    borderRadius: 6
};

const btn = {
    padding: '10px 16px',
    backgroundColor: '#007bff',
    color: '#fff',
    border: 'none',
    borderRadius: 6,
    cursor: 'pointer',
    fontWeight: 'bold'
};

export default SystemSettings;
